#include <iostream>
#include <fstream>
#include <memory>

class FileOpener {
public:
  FileOpener(const std::string& filename) : file_(filename) {
    if (!file_.is_open()) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileOpener() { file_.close(); }
  std::fstream& get_file() { return file_; }
private:
  std::fstream file_;
};

int main() {
  try {
    FileOpener file("mydata.txt"); // Resource (file) acquired
    file.get_file() << "Hello, RAII!\n";
  } catch (const std::runtime_error& e) {
    std::cerr << "Error: " << e.what() << '\n';
  }
  // File is automatically closed here (destructor called)
  return 0;
}
